<div class="section-head"><div><span class="eyebrow">Submission #<?=e($submission['submission_id'])?></span><h2><?=e($submission['problem_code'].'. '.$submission['problem_title'])?></h2><p class="muted"><?=e($submission['contest_title'])?> · <?=e($submission['user_name'])?></p></div><span class="badge badge-<?=e(strtolower($submission['verdict']))?>"><?=e(str_replace('_',' ',$submission['verdict']))?></span></div>
<section class="grid grid-3"><article class="card"><small class="muted">Language</small><h3><?=e($submission['language'])?></h3></article><article class="card"><small class="muted">Execution</small><h3><?=e($submission['execution_time_ms']??'—')?> ms</h3></article><article class="card"><small class="muted">Memory</small><h3><?=e($submission['memory_used_kb']??'—')?> KB</h3></article></section>
<section class="card"><div class="section-head"><h2>Source code</h2><span class="muted"><?=e($submission['submitted_at'])?></span></div><pre class="code-block"><?=e($submission['source_code'])?></pre><?php if($submission['judge_message']):?><h3>Judge message</h3><p><?=e($submission['judge_message'])?></p><?php endif;?></section>
<?php if(has_role('ORGANIZER')&&(int)$submission['organizer_user_id']===(int)user()['user_id']):?><form class="card form-grid" method="post" action="<?=e(url('/organizer/submissions/'.$submission['submission_id'].'/judge'))?>"><?=csrf_field()?><h2 class="field-full">Authorized review</h2><div class="field"><label for="verdict">Verdict</label><select id="verdict" name="verdict"><?php foreach(['ACCEPTED','WRONG_ANSWER','TIME_LIMIT_EXCEEDED','MEMORY_LIMIT_EXCEEDED','RUNTIME_ERROR','COMPILATION_ERROR','SYSTEM_ERROR'] as $v):?><option><?=$v?></option><?php endforeach;?></select></div><div class="field"><label for="execution_time">Execution time (ms)</label><input id="execution_time" name="execution_time" type="number" min="0" step=".001"></div><div class="field"><label for="memory_used">Memory (KB)</label><input id="memory_used" name="memory_used" type="number" min="0"></div><div class="field"><label for="judge_message">Message</label><input id="judge_message" name="judge_message"></div><button class="button field-full">Record verdict</button></form><?php endif;?>
